fn ContainsSequence(list: List[List[Int]], sub: List[Int]) -> Bool
  requires (len(list) >= 0)
  ensures (result == (exists i in 0..len(list): (sub == list[i])))
  effects pure
  example ContainsSequence([[1, 2], [3, 4]], [1, 2]) == true
  example ContainsSequence([[1, 2], [3, 4]], [5, 6]) == false
  example ContainsSequence([], [1, 2]) == false
{
  match list {
    [] => false
    [h, ..t] => if h == sub then true else ContainsSequence(t, sub)
  }
}

