fn ListLength(xs: List[Int]) -> Int
  requires true
  ensures result >= 0
  ensures result == len(xs)
  effects pure
  example ListLength([]) == 0
  example ListLength([1, 2, 3]) == 3
{
  match xs {
    [] => 0
    [_, ..t] => 1 + ListLength(t)
  }
}

fn MinOfTwo(a: Int, b: Int) -> Int
  requires a >= 0 and b >= 0
  ensures (result == a or result == b)
  ensures result <= a
  ensures result <= b
  effects pure
  example MinOfTwo(3, 2) == 2
  example MinOfTwo(1, 5) == 1
{
  if a <= b then a else b
}

fn SmallestListLength(s: List[List[Int]]) -> Int
  requires (len(s) > 0)
  ensures forall i in 0..len(s): (result <= len(s[i]))
  ensures exists i in 0..len(s): (result == len(s[i]))
  effects pure
  example SmallestListLength([[1, 2], [3]]) == 1
{
  match s {
    [h, ..t] => 
      match t {
        [] => ListLength(h)
        _ => MinOfTwo(ListLength(h), SmallestListLength(t))
      }
    [] => 0
  }
}

