fn LogicalAnd(x1: List[Bool], x2: List[Bool]) -> List[Bool]
  requires (len(x1) == len(x2))
  ensures (len(result) == len(x1))
  ensures forall i in 0..len(result): (result[i] == (x1[i] and x2[i]))
  effects pure
  example LogicalAnd([], []) == []
  example LogicalAnd([true], [true]) == [true]
  example LogicalAnd([true, false], [true, false]) == [true, false]
  example LogicalAnd([false, true], [false, false]) == [false, false]
{
  match x1 {
    [] => []
    [h1, ..t1] => match x2 {
      [] => []
      [h2, ..t2] => [h1 and h2] ++ LogicalAnd(t1, t2)
    }
  }
}

