  requires len(a) > 0
  ensures len(result) == len(a) - 1
  ensures forall i in 0..len(result): result[i] == a[i + 1]
  effects pure
  example Tail([1]) == []
  example Tail([1, 2, 3]) == [2, 3]
{
  match a {
    [] => []
    [_, ..t] => t
  }
}

fn Init(a: List[Int]) -> List[Int]
